"""Publish source-derived concept cards, a comparative plate and local indexes."""
from pathlib import Path
import json,hashlib,html,textwrap
from PIL import Image,ImageDraw,ImageFont
HERE=Path(__file__).resolve().parent;REPO=HERE.parents[1]
TRADE='experiments/selected_feeder/verification/REPORT.md'
TITLES={
'lead_screw':('Guided lead screw',1,7.30,'Selected architecture lineage','A guided screw and nut drive a reversible lateral pusher.','Selected for controllability and available corrected geometry/sizing evidence; the detailed selected study is FM08-R3.'),
'rack_pawl':('Rack and pawl',2,7.10,'Runner-up','A toothed drive advances the pusher; a pawl provides retention/indexing.','Positive engagement is the runner-up. Tooth/root support, backlash and skipped engagement remain engineering costs.'),
'spring_dual_gate':('Spring and two gates',3,6.90,'Retained alternative','Stored spring energy feeds the payload through a two-gate sequence.','Low powered-feed demand; the historical 15 N end-force assumption needs spring/governor redesign for the declared feed demand.'),
'belt_shuttle':('Belt shuttle',4,6.70,'Retained alternative','A tensioned belt moves the transfer shuttle along a guided path.','Retained packaging alternative; tension, compliance, retention and skipped engagement require evidence.'),
'indexed_drum':('Indexed drum',5,6.40,'Retained common-port concept','Four storage cells rotate toward one common extraction port.','Common-port packaging is retained; the R1 extraction transmission and index connection remain undeveloped.'),
'telescopic':('Telescopic carriage',6,6.05,'Retained compact-stowage concept','Nested stages extend a guided transfer carriage from a short stowed package.','Stage alignment, overlap, synchronization, stops and binding remain redesign requirements.'),
'pantograph':('Pantograph',7,5.50,'Retained linkage concept','A folding linkage converts a compact stowed form into transfer travel.','Collapsible storage remains research work; linkage connections, near-flat loads and joint play require redesign.')}
FONT='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';BOLD='/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
INK='#172128';MUTED='#42525d';LINE='#ccd2d5';ACC='#275c50'
def f(n,b=False):return ImageFont.truetype(BOLD if b else FONT,n)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def wrapped(draw,text,xy,width,font,fill=INK,line=1.27):
 x,y=xy;row=''
 for word in text.split():
  candidate=(row+' '+word).strip()
  if draw.textlength(candidate,font=font)>width and row:draw.text((x,y),row,font=font,fill=fill);y+=font.size*line;row=word
  else:row=candidate
 if row:draw.text((x,y),row,font=font,fill=fill);y+=font.size*line
 return y
provenance=json.loads((HERE/'RENDER_PROVENANCE.json').read_text());cards=HERE/'cards';cards.mkdir(exist_ok=True);records=[]
for r in provenance['renders']:
 key=r['concept'];title,rank,score,role,principle,rationale=TITLES[key];raw=Image.open(REPO/r['path']).convert('RGB');assert sha(REPO/r['path'])==r['sha256']
 im=Image.new('RGB',(1800,1680),'white');im.paste(raw,(0,200));d=ImageDraw.Draw(im);d.text((70,40),title,font=f(64,True),fill=INK);d.text((70,126),'FDR09-R1 · historical concept geometry',font=f(44),fill=MUTED)
 # Same physical width and image pixel count in every source render.
 length=1800*.5/r['camera']['field_width_m'];x=95;y=1530
 d.line((x,y,x+length,y),fill=INK,width=6);d.line((x,y-11,x,y+11),fill=INK,width=5);d.line((x+length,y-11,x+length,y+11),fill=INK,width=5)
 d.text((x,1550),'500 mm · projection plane',font=f(38),fill=INK);d.text((950,1550),'Native-CAD-derived Blender view',font=f(36),fill=MUTED)
 path=cards/(key+'.png');im.save(path)
 records.append({'concept':key,'title':title,'rank':rank,'weighted_judgment':score,'trade_role':role,'principle':principle,'rationale':rationale,'image_path':str(path.relative_to(REPO)),'image_sha256':sha(path),'alt_text':f'{title}: preserved FDR09-R1 four-payload stowed native CAD, shown with the same orthographic view and physical scale as the six other concepts.','geometry_revision':'FDR09-R1-2026-10-22','geometry_status':'historical common-boundary concept','trade_revision':'FDR10-R0 / D27-R2','trade_source':TRADE,'trade_source_sha256':sha(REPO/TRADE),'source_native':r['mesh_source']['native_path'],'source_native_sha256':r['mesh_source']['native_sha256'],'source_step':r['mesh_source']['step_path'],'source_step_sha256':r['mesh_source']['step_sha256'],'render_provenance':'figures/feeder-concepts/RENDER_PROVENANCE.json','render':r})
# Source-derived details expose the actual represented drive parts; positions are unchanged.
for record in records:
 detail=record['render']['detail'];raw=Image.open(REPO/detail['path']).convert('RGB');im=Image.new('RGB',(1800,1680),'white');im.paste(raw,(0,200));draw=ImageDraw.Draw(im)
 draw.text((70,40),record['title']+' · drive detail',font=f(60,True),fill=INK)
 scope='Rotor and axle; other source geometry hidden'if record['concept']=='indexed_drum'else'Original positions; payload and cassette shell hidden'
 draw.text((70,126),'FDR09-R1 · '+scope,font=f(40),fill=MUTED)
 millimetres=100 if detail['camera']['field_width_m']<1.5 else 250;length=1800*(millimetres/1000)/detail['camera']['field_width_m'];x=95;y=1530
 draw.line((x,y,x+length,y),fill=INK,width=6);draw.line((x,y-11,x,y+11),fill=INK,width=5);draw.line((x+length,y-11,x+length,y+11),fill=INK,width=5)
 draw.text((x,1550),str(millimetres)+' mm · projection plane',font=f(38),fill=INK);draw.text((950,1550),'Native-CAD geometry detail',font=f(36),fill=MUTED)
 path=cards/(record['concept']+'_detail.png');im.save(path);record['detail_image_path']=str(path.relative_to(REPO));record['detail_image_sha256']=sha(path);record['detail_scope']=detail['scope'];record['detail_scale_mm']=millimetres
# A single plate uses unannotated source renders; all plate labels remain >=44px.
plate=Image.new('RGB',(3200,2340),'white');d=ImageDraw.Draw(plate);d.text((70,45),'Seven feeder concepts · one comparison boundary',font=f(68,True),fill=INK);d.text((70,135),'Preserved FDR09-R1 geometry · four mixed 1U/3U payload surrogates',font=f(46),fill=MUTED)
for i,r in enumerate(records):
 x=(i%4)*800;y=230+(i//4)*920;d.line((x+35,y,x+765,y),fill=LINE,width=3);d.text((x+35,y+22),f'{r["rank"]:02d}  {r["title"]}',font=f(44,True),fill=INK)
 image=Image.open(REPO/r['render']['path']).convert('RGB');image.thumbnail((800,600),Image.Resampling.LANCZOS);plate.paste(image,(x,y+115))
 d=ImageDraw.Draw(plate);role_bottom=wrapped(d,r['trade_role'],(x+35,y+710),730,f(44),ACC)
 assert role_bottom<y+845
 length=800*.5/r['render']['camera']['field_width_m'];d.line((x+40,y+880,x+40+length,y+880),fill=INK,width=5);d.text((x+55+length,y+855),'500 mm',font=f(44),fill=MUTED)
x=2435;y=1190
for line in ['Shared orthographic view','Shared physical scale','Individually centered','Blue: payload envelope','Copper: drive geometry','Grey: structure/custody','Pale: actuator envelopes']:
 d.text((x,y),line,font=f(42),fill=MUTED);y+=68
d.text((70,2150),'Geometry: historical FDR09-R1. Trade roles: later FDR10-R0 / D27-R2 selection record.',font=f(44),fill=INK)
d.text((70,2220),'Guided lead screw was developed further in FM08-R3. Current twelve-3U ACR1 is a separate assembly.',font=f(44),fill=MUTED)
plate.save(HERE/'seven_feeder_concepts.png');plate.save(HERE/'seven_feeder_concepts.pdf',resolution=450)
field=records[0]['render']['camera'];intro=f'''Seven preserved four-payload concepts are shown with the same orthographic direction, role colours and {field['field_width_m']:.3f} m × {field['field_height_m']:.3f} m field. Each model is centered on its projected geometry; every scale bar is 500 mm in the image plane. All native parts are retained in those full source views. Expand a drive detail to inspect the actual represented mechanism in its original position; its individual scale is printed. Blue solids are payload proxies and pale blocks are unselected actuator/sensor envelopes.'''
# GitHub-native index is canonical; HTML is the local responsive gallery.
md=['# Seven feeder concepts','',intro,'','The displayed geometry is **FDR09-R1 historical concept geometry** for two 1U and two 3U surrogates. Roles and ranks come from the later [FDR10-R0 / D27-R2 architecture decision](../../'+TRADE+'). The selected guided lead-screw architecture was developed in FM08-R3; the current twelve-3U ACR1 assembly retains its own identity.','', '[Open responsive local gallery](../../docs/feeder-concepts.html) · [Full comparison plate](seven_feeder_concepts.png) · [Print plate](seven_feeder_concepts.pdf) · [Source and hash manifest](MANIFEST.json)','']
for r in records:
 md += [f'## {r["rank"]}. {r["title"]} · {r["trade_role"]}','',f'![{r["alt_text"]}](cards/{r["concept"]}.png)','',r['principle']+' '+r['rationale'],'',f'<details><summary>Source-derived drive detail</summary>\n\n![{r["title"]} source drive detail, source positions retained](cards/{r["concept"]}_detail.png)\n\n{r["detail_scope"]}. Image-plane scale: {r["detail_scale_mm"]} mm. The [view provenance](RENDER_PROVENANCE.json) lists every displayed and omitted source object.\n\n</details>','',f'**Display:** FDR09-R1, stowed four-payload concept. **Trade:** FDR10-R0 weighted judgment {r["weighted_judgment"]:.2f}/10. [Native CAD](../../{r["source_native"]}) · [STEP](../../{r["source_step"]}) · [Trade source](../../{TRADE})','']
md += ['## Evidence and reproduction','','Scores are declared engineering judgments, not measured reliability. The original [FDR09 gate outcomes](../../experiments/feeder_common_boundary/release/D27_GATES.json) and [comparison report](../../experiments/feeder_common_boundary/release/READ_ME.md) remain unchanged; the later architecture selection uses its own decision rule. These views depict the preserved historical concept geometry.','','Regenerate visualization meshes with `PYTHONPATH=/usr/lib/freecad-python3/lib /usr/bin/python3 figures/feeder-concepts/export_meshes.py`. Run `blender -b -t 4 -P figures/feeder-concepts/render_concepts.py`, then `python3 figures/feeder-concepts/build_gallery.py`. The editable Blender scene contains all seven native-derived scenes. Run `python3 figures/feeder-concepts/package_scene.py` to create the lossless XZ publication package. Restore it with `xz --decompress --keep figures/feeder-concepts/FDR09_seven_concepts.blend.xz`; the decompressed identity is recorded in `SCENE_ARCHIVE.json`. Meshes are for display, not structural/contact analysis.','','Project-created geometry, renders, plate and source: [CC BY 4.0](../../LICENSE), with attribution in [NOTICE](../../NOTICE). Font software is an installed rendering dependency and is not bundled. [Scientific figure conventions](../../docs/FIGURE_STANDARD.md).','']
(HERE/'README.md').write_text('\n'.join(md))
article=[]
for r in records:
 native='../'+r['source_native'];step='../'+r['source_step'];image='../'+r['image_path'];article.append(f'''<article id="{r['concept']}"><div class="card-head"><span class="rank">{r['rank']:02d}</span><div><h2>{r['title']}</h2><span class="role">{r['trade_role']}</span></div></div><a href="{image}"><img src="{image}" width="1800" height="1680" alt="{html.escape(r['alt_text'])}" loading="lazy"></a><div class="copy"><div class="revision">FDR09-R1 / HISTORICAL GEOMETRY</div><p>{r['principle']}</p><p>{r['rationale']}</p><details><summary>Inspect source drive geometry</summary><a href="../{r['detail_image_path']}"><img src="../{r['detail_image_path']}" alt="{r['title']} original-position CAD drive detail; {html.escape(r['detail_scope'])}" width="1800" height="1680" loading="lazy"></a><p>{r['detail_scope']}. The {r['detail_scale_mm']} mm scale bar is in the image plane. <a href="../figures/feeder-concepts/RENDER_PROVENANCE.json">Displayed/omitted source parts</a>.</p></details><p class="judgment">FDR10-R0 weighted judgment: {r['weighted_judgment']:.2f}/10</p><div class="sources"><a href="{native}">Native CAD</a><a href="{step}">STEP</a><a href="../{TRADE}">Trade rationale</a></div></div></article>''')
css='''*{box-sizing:border-box}body{margin:0;background:#f6f5f1;color:#172128;font:17px/1.65 system-ui,sans-serif}a{color:#275c50;text-underline-offset:4px}a:focus-visible{outline:3px solid #986c20;outline-offset:5px}.skip{position:absolute;top:-100px;background:white;padding:12px}.skip:focus{top:10px}.wrap{width:min(1260px,calc(100% - 56px));margin:auto}header{background:#11161c;color:#f6f5f1;padding:24px 0}header .wrap{display:flex;justify-content:space-between;gap:25px;align-items:center}header a{color:#bfe3cf}.brand{font-weight:800;letter-spacing:.12em;text-decoration:none}nav{display:flex;flex-wrap:wrap;gap:22px;font-size:14px}.intro{padding:65px 0 45px}.eyebrow,.revision{font:12px ui-monospace,monospace;letter-spacing:.12em;color:#48645a}h1{font-size:clamp(40px,6vw,70px);font-weight:500;line-height:1.05;letter-spacing:-.045em;max-width:17ch;margin:20px 0 30px}h2{font-size:23px;line-height:1.2;margin:0 0 8px;font-weight:550}p{max-width:85ch}.intro>p{font-size:19px}.note{border-left:3px solid #6b8e7b;padding:18px 25px;background:#e9eeea;margin:30px 0;font-size:15px}.downloads{display:flex;gap:25px;flex-wrap:wrap;font-size:14px;margin-top:30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:26px;padding-bottom:65px}article{background:white;border:1px solid #ccd2d5;min-width:0}.card-head{display:flex;gap:18px;align-items:start;padding:25px 28px;border-bottom:1px solid #e4e7e7}.rank{font:28px ui-monospace,monospace;color:#64746b}.role{font-size:13px;color:#275c50}img{display:block;width:100%;height:auto}.copy{padding:26px 28px}.copy p{font-size:15px}details{border-top:1px solid #ccd2d5;padding:17px 0;margin-top:20px}summary{cursor:pointer;font-size:14px;color:#275c50}details img{margin-top:18px}.judgment{font:12px ui-monospace,monospace;color:#53635b;padding:15px 0}.sources{display:flex;gap:22px;flex-wrap:wrap;font-size:14px}footer{border-top:1px solid #ccd2d5;padding:45px 0 65px;color:#4b5b62;font-size:13px}footer p{max-width:100ch}@media(max-width:760px){.wrap{width:calc(100% - 34px)}header .wrap{display:block}nav{margin-top:18px;gap:12px 20px}.intro{padding-top:45px}.grid{grid-template-columns:1fr}.card-head,.copy{padding:22px}.intro>p{font-size:17px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}'''
